-- Generated by scripts/consolidated-sql.ts. Read-only aggregate RPC.
-- Approved for local implementation/testing only; NOT applied to production.
-- Requires existing enterprise_licenses and incremental annex8_* schema.
CREATE OR REPLACE FUNCTION public.mlrs_consolidated_preview(p_period_type text, p_year integer, p_index integer DEFAULT 1)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER
SET search_path = pg_catalog, public SET timezone = 'UTC' AS $function$
DECLARE size integer; period_start date; period_end date;
BEGIN
 size := CASE p_period_type WHEN 'MONTH' THEN 1 WHEN 'QUARTER' THEN 3 WHEN 'SEMESTER' THEN 6 WHEN 'YEAR' THEN 12 ELSE NULL END;
 IF size IS NULL OR p_year IS NULL OR p_year NOT BETWEEN 1900 AND 2200 OR p_index IS NULL OR p_index NOT BETWEEN 1 AND 12/size THEN
   RAISE EXCEPTION 'Invalid consolidated period' USING ERRCODE='22023';
 END IF;
 period_start := make_date(p_year,1+(p_index-1)*size,1);
 period_end := (period_start + size * interval '1 month' - interval '1 day')::date;
 RETURN (WITH RECURSIVE
cfg0 AS (SELECT CAST(period_start AS DATE) AS s, CAST(period_end AS DATE) AS e, CAST(CURRENT_TIMESTAMP AS timestamptz) AS cutoff),
cfg AS (SELECT *, ((EXTRACT(YEAR FROM e)-EXTRACT(YEAR FROM s))*12 + EXTRACT(MONTH FROM e)-EXTRACT(MONTH FROM s)+1) AS months FROM cfg0),
windows AS (
 SELECT 'cur' AS w, s, e FROM cfg
 UNION ALL SELECT 'prev', CAST((s + (-months) * INTERVAL '1 month') AS DATE), CAST((s + (-1) * INTERVAL '1 day') AS DATE) FROM cfg
 UNION ALL SELECT 'ytd', date_trunc('year', s)::date, e FROM cfg
 UNION ALL SELECT 'prev_ytd', date_trunc('year', (s + (-months) * INTERVAL '1 month'))::date, CAST((s + (-1) * INTERVAL '1 day') AS DATE) FROM cfg
),
months AS (
 SELECT LEAST((SELECT MIN(s) FROM windows),(SELECT s FROM cfg)) AS d
 UNION ALL SELECT CAST((d + (1) * INTERVAL '1 month') AS DATE) FROM months WHERE (d + (1) * INTERVAL '1 month') <= (SELECT e FROM cfg)
),
licences AS (
 SELECT l.license_number AS licence_no, COALESCE(NULLIF(l.company_name_kh,''),l.company_name) AS name,
 COALESCE(NULLIF(l.province_city,''),'មិនមានទិន្នន័យ') AS province, p.licence_type,
 CAST(l.license_issue_date AS DATE) AS issued, CAST(l.license_expiry_date AS DATE) AS expires
 FROM enterprise_licenses l LEFT JOIN annex8_licence_profiles p ON p.license_number=l.license_number
),
eligible AS (
 SELECT r.*, ROW_NUMBER() OVER (PARTITION BY r.licence_no,r.period_month ORDER BY r.submitted_at DESC,r.id DESC) AS version_rank,
 (SELECT MIN(original.submitted_at) FROM annex8_reports original WHERE original.licence_no=r.licence_no AND original.period_month=r.period_month AND original.status IN ('SUBMITTED','ACCEPTED','RETURNED') AND original.submitted_at<=cfg.cutoff) AS first_received
 FROM annex8_reports r CROSS JOIN cfg
 WHERE r.status IN ('SUBMITTED','ACCEPTED') AND r.submitted_at <= cfg.cutoff
 AND r.period_month BETWEEN to_char((SELECT MIN(s) FROM windows), 'YYYY-MM') AND to_char(cfg.e, 'YYYY-MM')
),
selected AS (SELECT * FROM eligible WHERE version_rank=1),
requirements AS (
 SELECT w.w,l.*, to_char(d, 'YYYY-MM') AS period_month, r.id AS report_uuid, r.report_type, r.report_id,
 CASE WHEN r.first_received >= ((((d + (1) * INTERVAL '1 month') + (7) * INTERVAL '1 day') + (-7) * INTERVAL '1 hour') AT TIME ZONE 'UTC') THEN 1 ELSE 0 END AS is_late,
 CASE WHEN EXISTS (SELECT 1 FROM annex8_reports rr WHERE rr.licence_no=l.licence_no AND rr.period_month=to_char(d, 'YYYY-MM') AND rr.status='RETURNED') THEN 1 ELSE 0 END AS has_returned
 FROM windows w JOIN licences l ON l.issued<=w.e AND l.expires>=w.s
 JOIN months ON d>=w.s AND d<=w.e AND l.issued<=CAST(((d + (1) * INTERVAL '1 month') + (-1) * INTERVAL '1 day') AS DATE) AND l.expires>=d
 LEFT JOIN selected r ON r.licence_no=l.licence_no AND r.period_month=to_char(d, 'YYYY-MM')
),
population AS (
 SELECT w,licence_no,name,province,licence_type, COUNT(*) AS required,
 SUM(CASE WHEN report_uuid IS NULL THEN 1 ELSE 0 END) AS missing, SUM(is_late) AS late,
 SUM(CASE WHEN report_type='NIL' THEN 1 ELSE 0 END) AS nil, SUM(CASE WHEN report_type='AMENDMENT' THEN 1 ELSE 0 END) AS amend, MAX(has_returned) AS returned,
 string_agg(CASE WHEN report_uuid IS NULL THEN period_month ELSE NULL END, ', ' ORDER BY period_month) AS missing_months,
 string_agg(CASE WHEN is_late=1 THEN period_month ELSE NULL END, ', ' ORDER BY period_month) AS late_months
 FROM requirements GROUP BY w,licence_no,name,province,licence_type
),
submission AS (
 SELECT w, COALESCE(licence_type,'UNKNOWN') AS licence_type, COUNT(*) AS active,
 SUM(CASE WHEN missing=0 THEN 1 ELSE 0 END) AS submitted, SUM(CASE WHEN missing=0 AND late=0 THEN 1 ELSE 0 END) AS ontime,
 SUM(CASE WHEN missing=0 AND late>0 THEN 1 ELSE 0 END) AS late, SUM(CASE WHEN missing>0 THEN 1 ELSE 0 END) AS notsub,
 SUM(CASE WHEN nil>0 THEN 1 ELSE 0 END) AS nil, SUM(CASE WHEN amend>0 THEN 1 ELSE 0 END) AS amend, SUM(CASE WHEN returned>0 THEN 1 ELSE 0 END) AS returned
 FROM population GROUP BY w,licence_type
 UNION ALL SELECT w,'TOTAL',COUNT(*),SUM(CASE WHEN missing=0 THEN 1 ELSE 0 END),SUM(CASE WHEN missing=0 AND late=0 THEN 1 ELSE 0 END),SUM(CASE WHEN missing=0 AND late>0 THEN 1 ELSE 0 END),SUM(CASE WHEN missing>0 THEN 1 ELSE 0 END),SUM(CASE WHEN nil>0 THEN 1 ELSE 0 END),SUM(CASE WHEN amend>0 THEN 1 ELSE 0 END),SUM(CASE WHEN returned>0 THEN 1 ELSE 0 END) FROM population GROUP BY w
),
entries AS (
 SELECT r.id AS report_uuid,r.licence_no,r.period_month,i.id AS entry_id,i.op_code AS op,
 i.category,i.province,i.instrument_name,i.serial_no
 FROM selected r JOIN annex8_report_instruments i ON i.report_uuid=r.id WHERE i.deleted_at IS NULL AND r.report_type<>'NIL'
 UNION ALL SELECT r.id,r.licence_no,r.period_month,i.id,'R',i.category,i.province,i.instrument_name,i.serial_no
 FROM selected r JOIN annex8_report_repairs i ON i.report_uuid=r.id WHERE i.deleted_at IS NULL AND r.report_type<>'NIL'
),
activity AS (
 SELECT w.w,a.* FROM entries a JOIN windows w ON a.period_month BETWEEN to_char(w.s, 'YYYY-MM') AND to_char(w.e, 'YYYY-MM')
),
category_counts AS (
 SELECT w,category,SUM(CASE WHEN op='M' THEN 1 ELSE 0 END) AS m, SUM(CASE WHEN op='I' THEN 1 ELSE 0 END) AS i, SUM(CASE WHEN op='R' THEN 1 ELSE 0 END) AS r FROM activity GROUP BY w,category
 UNION ALL SELECT w,'TOTAL',SUM(CASE WHEN op='M' THEN 1 ELSE 0 END) AS m, SUM(CASE WHEN op='I' THEN 1 ELSE 0 END) AS i, SUM(CASE WHEN op='R' THEN 1 ELSE 0 END) AS r FROM activity GROUP BY w
),
licence_counts AS (SELECT w,licence_no,SUM(CASE WHEN op='M' THEN 1 ELSE 0 END) AS m, SUM(CASE WHEN op='I' THEN 1 ELSE 0 END) AS i, SUM(CASE WHEN op='R' THEN 1 ELSE 0 END) AS r FROM activity GROUP BY w,licence_no),
province_counts AS (
 SELECT COALESCE(NULLIF(province,''),'មិនមានទិន្នន័យ') AS province,
 SUM(CASE WHEN op='I' THEN 1 ELSE 0 END) AS installed,SUM(CASE WHEN op='R' THEN 1 ELSE 0 END) AS repairs,COUNT(*) AS total
 FROM activity WHERE w='cur' AND op IN ('I','R') GROUP BY province
),
province_total AS (SELECT SUM(CASE WHEN op='I' THEN 1 ELSE 0 END) AS installed,SUM(CASE WHEN op='R' THEN 1 ELSE 0 END) AS repairs,COUNT(*) AS total FROM activity WHERE w='cur' AND op IN ('I','R')),
annex_population AS (
 SELECT * FROM population WHERE w='cur'
 UNION ALL SELECT 'cur',l.licence_no,l.name,l.province,l.licence_type,0,0,0,0,0,0,NULL,NULL FROM licences l
 WHERE EXISTS(SELECT 1 FROM activity a WHERE a.w='cur' AND a.licence_no=l.licence_no)
 AND NOT EXISTS(SELECT 1 FROM population p WHERE p.w='cur' AND p.licence_no=l.licence_no)
),
annex AS (
 SELECT p.*,COALESCE(a.m,0) AS m,COALESCE(a.i,0) AS i,COALESCE(a.r,0) AS r
 FROM annex_population p LEFT JOIN licence_counts a ON a.w=p.w AND a.licence_no=p.licence_no
),
seal_rows AS (
 SELECT r.id AS report_uuid,i.id AS entry_id,r.licence_no,i.instrument_name,i.serial_no,i.seal_removed_no,i.notification_no
 FROM selected r CROSS JOIN cfg
 JOIN annex8_report_repairs i ON i.report_uuid=r.id
 WHERE r.period_month BETWEEN to_char(cfg.s, 'YYYY-MM') AND to_char(cfg.e, 'YYYY-MM') AND i.deleted_at IS NULL AND i.seal_broken=true AND r.report_type<>'NIL'
),
seals_count AS (SELECT w.w,COUNT(*) AS n FROM windows w JOIN selected r ON r.period_month BETWEEN to_char(w.s, 'YYYY-MM') AND to_char(w.e, 'YYYY-MM') JOIN annex8_report_repairs i ON i.report_uuid=r.id WHERE i.deleted_at IS NULL AND i.seal_broken=true AND r.report_type<>'NIL' GROUP BY w.w),
expiry AS (SELECT w.w,COUNT(*) AS n FROM windows w JOIN licences l ON l.issued<=w.e AND l.expires>w.e AND l.expires<=CAST((w.e + (90) * INTERVAL '1 day') AS DATE) GROUP BY w.w),
diagnostics AS (
 SELECT
 (SELECT COUNT(*) FROM licences WHERE issued IS NULL OR expires IS NULL OR issued>expires) AS invalid_validity,
 (SELECT COUNT(*) FROM selected r LEFT JOIN licences l ON l.licence_no=r.licence_no WHERE l.licence_no IS NULL) AS orphan_reports,
 (SELECT COUNT(*) FROM eligible a WHERE a.report_type='AMENDMENT' AND 1 <> (
   SELECT COUNT(*) FROM annex8_reports root WHERE root.licence_no=a.licence_no AND root.period_month=a.period_month
   AND root.report_type<>'AMENDMENT' AND root.status IN ('SUBMITTED','ACCEPTED','RETURNED') AND (root.report_id=a.original_report_id OR CAST(root.id AS TEXT)=a.original_report_id)
   AND root.submitted_at IS NOT NULL AND root.submitted_at<=a.submitted_at)) AS invalid_amendments,
 (SELECT COUNT(*) FROM annex8_reports CROSS JOIN cfg WHERE status IN ('SUBMITTED','ACCEPTED') AND submitted_at IS NULL AND period_month BETWEEN to_char((SELECT MIN(s) FROM windows), 'YYYY-MM') AND to_char(cfg.e, 'YYYY-MM')) AS missing_receipts,
 (SELECT COUNT(*) FROM activity WHERE category IS NULL OR category NOT IN ('NAWI','WEIGHBRIDGE','WEIGHTS','FUEL_DISPENSER','LPG_DISPENSER','ELEC_METER','WATER_METER','EV_CHARGER','OTHER')) AS unknown_categories,
 (SELECT COUNT(*) FROM selected r WHERE r.report_type='NIL' AND (EXISTS(SELECT 1 FROM annex8_report_instruments i WHERE i.report_uuid=r.id AND i.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM annex8_report_repairs i WHERE i.report_uuid=r.id AND i.deleted_at IS NULL))) AS nil_with_activity
)
SELECT jsonb_build_object('version',1,'data_as_of',(SELECT cutoff FROM cfg),
 'submission',(SELECT COALESCE(jsonb_agg(jsonb_build_object('window',w,'type',licence_type,'active',active,'submitted',submitted,'ontime',ontime,'late',late,'notsub',notsub,'nil',nil,'amend',amend,'returned',returned)), '[]'::jsonb) FROM submission),
 'categories',(SELECT COALESCE(jsonb_agg(jsonb_build_object('window',w,'category',category,'m', m, 'i', i, 'r', r)), '[]'::jsonb) FROM category_counts),
 'licensees',(SELECT COALESCE(jsonb_agg(jsonb_build_object('licence_no',licence_no,'name',name,'province',province,'type',licence_type,'required',required,'missing',missing,'late',late,'missing_months',missing_months,'late_months',late_months,'m', m, 'i', i, 'r', r)), '[]'::jsonb) FROM annex),
 'provinces',(SELECT COALESCE(jsonb_agg(jsonb_build_object('province',province,'installed',installed,'repairs',repairs,'total',total)), '[]'::jsonb) FROM province_counts),
 'province_total',(SELECT jsonb_build_object('installed',COALESCE(installed,0),'repairs',COALESCE(repairs,0),'total',total) FROM province_total),
 'seals',(SELECT COALESCE(jsonb_agg(jsonb_build_object('entry_id',entry_id,'licence_no',licence_no,'instrument',instrument_name,'serial_no',serial_no,'seal_no',seal_removed_no,'notification_no',notification_no)), '[]'::jsonb) FROM seal_rows),
 'seal_counts',(SELECT COALESCE(jsonb_agg(jsonb_build_object('window',w,'count',n)), '[]'::jsonb) FROM seals_count),
 'expiry',(SELECT COALESCE(jsonb_agg(jsonb_build_object('window',w,'count',n)), '[]'::jsonb) FROM expiry),
 'diagnostics',(SELECT jsonb_build_object('invalid_validity',invalid_validity,'orphan_reports',orphan_reports,'invalid_amendments',invalid_amendments,'missing_receipts',missing_receipts,'unknown_categories',unknown_categories,'nil_with_activity',nil_with_activity) FROM diagnostics),
 'sources',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'report_id',report_id,'licence_no',licence_no,'period_month',period_month)), '[]'::jsonb) FROM selected)) AS result);
END;
$function$;
REVOKE ALL ON FUNCTION public.mlrs_consolidated_preview(text,integer,integer) FROM PUBLIC;
DO $grant$ BEGIN
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON FUNCTION public.mlrs_consolidated_preview(text,integer,integer) FROM anon; END IF;
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON FUNCTION public.mlrs_consolidated_preview(text,integer,integer) FROM authenticated; END IF;
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN GRANT EXECUTE ON FUNCTION public.mlrs_consolidated_preview(text,integer,integer) TO service_role; END IF;
END $grant$;
COMMENT ON FUNCTION public.mlrs_consolidated_preview(text,integer,integer) IS 'Complete read-only SQL aggregates; API enforces NMC staff authorization. No source-row pagination or writes.';
